"use strict";(globalThis.webpackChunkmy_docusaurus=globalThis.webpackChunkmy_docusaurus||[]).push([[9724],{6048(n){n.exports=JSON.parse('{"archive":{"blogPosts":[{"id":"tim-hieu-python","metadata":{"permalink":"/my-docusaurus/blog/tim-hieu-python","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-02-02-tim-hieu-ve-Python.md","source":"@site/blog/2026-02-02-tim-hieu-ve-Python.md","title":"T\xecm hi\u1ec3u v\u1ec1 ng\xf4n ng\u1eef Python \u2013 T\u1eeb t\u1ed5ng quan \u0111\u1ebfn c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng b\xean trong","description":"1. T\xecm hi\u1ec3u chung v\u1ec1 ng\xf4n ng\u1eef Python","date":"2026-02-02T00:00:00.000Z","tags":[{"inline":true,"label":"python","permalink":"/my-docusaurus/blog/tags/python"},{"inline":true,"label":"interpreted","permalink":"/my-docusaurus/blog/tags/interpreted"},{"inline":true,"label":"compiled","permalink":"/my-docusaurus/blog/tags/compiled"},{"inline":true,"label":"cpython","permalink":"/my-docusaurus/blog/tags/cpython"},{"inline":true,"label":"memory-management","permalink":"/my-docusaurus/blog/tags/memory-management"}],"readingTime":5.74,"hasTruncateMarker":false,"authors":[{"name":"Mai Duc Anh","title":"Blogger & Developer","url":"https://github.com/maiducanha1anh","imageURL":"https://github.com/yourusername.png","key":"admin","page":null}],"frontMatter":{"slug":"tim-hieu-python","sidebar_position":1,"title":"T\xecm hi\u1ec3u v\u1ec1 ng\xf4n ng\u1eef Python \u2013 T\u1eeb t\u1ed5ng quan \u0111\u1ebfn c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng b\xean trong","authors":["admin"],"tags":["python","interpreted","compiled","cpython","memory-management"]},"unlisted":false,"nextItem":{"title":"H\u01b0\u1edbng d\u1eabn t\u1ea1o Blog c\xe1 nh\xe2n b\u1eb1ng Docusaurus","permalink":"/my-docusaurus/blog/bai-viet-dau-tien"}},"content":"## 1. T\xecm hi\u1ec3u chung v\u1ec1 ng\xf4n ng\u1eef Python\\r\\n\\r\\nPython l\xe0 m\u1ed9t ng\xf4n ng\u1eef l\u1eadp tr\xecnh b\u1eadc cao (high-level language), \u0111\u01b0\u1ee3c t\u1ea1o ra b\u1edfi **Guido van Rossum** v\xe0 ch\xednh th\u1ee9c ra m\u1eaft l\u1ea7n \u0111\u1ea7u v\xe0o n\u0103m **1991**. Python \u0111\u01b0\u1ee3c thi\u1ebft k\u1ebf v\u1edbi tri\u1ebft l\xfd **\u0111\u01a1n gi\u1ea3n \u2013 d\u1ec5 \u0111\u1ecdc \u2013 d\u1ec5 h\u1ecdc \u2013 d\u1ec5 b\u1ea3o tr\xec**, gi\xfap l\u1eadp tr\xecnh vi\xean t\u1eadp trung nhi\u1ec1u h\u01a1n v\xe0o logic nghi\u1ec7p v\u1ee5 thay v\xec c\xfa ph\xe1p ph\u1ee9c t\u1ea1p.\\r\\n\\r\\n### \u0110\u1eb7c \u0111i\u1ec3m n\u1ed5i b\u1eadt c\u1ee7a Python\\r\\n\\r\\n- C\xfa ph\xe1p g\u1ea7n v\u1edbi ng\xf4n ng\u1eef t\u1ef1 nhi\xean, d\u1ec5 \u0111\u1ecdc\\r\\n- Ng\xf4n ng\u1eef **\u0111a m\u1ee5c \u0111\xedch**: Web, AI, Data Science, Automation, Game, IoT\\r\\n- H\u1ec7 sinh th\xe1i th\u01b0 vi\u1ec7n phong ph\xfa (NumPy, Pandas, TensorFlow, Django, Flask, ...)\\r\\n- Ch\u1ea1y \u0111a n\u1ec1n t\u1ea3ng: Windows, Linux, macOS\\r\\n- C\u1ed9ng \u0111\u1ed3ng l\u1edbn, t\xe0i li\u1ec7u \u0111\u1ea7y \u0111\u1ee7\\r\\n\\r\\nPython \u0111\u1eb7c bi\u1ec7t ph\xf9 h\u1ee3p cho:\\r\\n- Sinh vi\xean IT\\r\\n- Ng\u01b0\u1eddi m\u1edbi h\u1ecdc l\u1eadp tr\xecnh\\r\\n- C\xe1c h\u1ec7 th\u1ed1ng c\u1ea7n ph\xe1t tri\u1ec3n nhanh (Rapid Development)\\r\\n\\r\\n---\\r\\n\\r\\n## 2. Interpreted vs Compiled \u2013 C\u01a1 ch\u1ebf th\xf4ng d\u1ecbch v\xe0 bi\xean d\u1ecbch\\r\\n\\r\\nKhi n\xf3i \u0111\u1ebfn c\xe1ch m\u1ed9t ng\xf4n ng\u1eef \u0111\u01b0\u1ee3c th\u1ef1c thi, ta th\u01b0\u1eddng ph\xe2n bi\u1ec7t hai kh\xe1i ni\u1ec7m: **Compiled** v\xe0 **Interpreted**.\\r\\n\\r\\n### Compiled Language (Ng\xf4n ng\u1eef bi\xean d\u1ecbch)\\r\\n\\r\\nV\xed d\u1ee5: C, C++, Go\\r\\n\\r\\n**Quy tr\xecnh:**\\r\\n\\r\\nSource Code (.c) <br />\\r\\n\u2193 <br />\\r\\nCompiler <br />\\r\\n\u2193 <br />\\r\\nMachine Code (.exe) <br />\\r\\n\\r\\n\\r\\n\u0110\u1eb7c \u0111i\u1ec3m:\\r\\n- Bi\xean d\u1ecbch **to\xe0n b\u1ed9** ch\u01b0\u01a1ng tr\xecnh tr\u01b0\u1edbc khi ch\u1ea1y\\r\\n- Ch\u1ea1y nhanh, hi\u1ec7u n\u0103ng cao\\r\\n- Ph\u1ee5 thu\u1ed9c h\u1ec7 \u0111i\u1ec1u h\xe0nh v\xe0 ki\u1ebfn tr\xfac CPU\\r\\n- Kh\xf3 debug h\u01a1n\\r\\n\\r\\n---\\r\\n\\r\\n### Interpreted Language (Ng\xf4n ng\u1eef th\xf4ng d\u1ecbch)\\r\\n\\r\\nV\xed d\u1ee5: Python, JavaScript, PHP\\r\\n\\r\\nQuy tr\xecnh:\\r\\n\\r\\nSource Code (.py) <br />\\r\\n\u2193 <br />\\r\\nInterpreter <br />\\r\\n\u2193 <br />\\r\\nTh\u1ef1c thi t\u1eebng d\xf2ng <br />\\r\\n\\r\\n\\r\\n\u0110\u1eb7c \u0111i\u1ec3m:\\r\\n- Kh\xf4ng c\u1ea7n t\u1ea1o file `.exe`\\r\\n- D\u1ec5 debug, d\u1ec5 h\u1ecdc\\r\\n- Th\u01b0\u1eddng ch\u1eadm h\u01a1n compiled language\\r\\n\\r\\n\u26a0\ufe0f **Python kh\xf4ng ho\xe0n to\xe0n l\xe0 interpreted thu\u1ea7n t\xfay** \u2013 \u0111i\u1ec1u n\xe0y s\u1ebd r\xf5 h\u01a1n khi t\xecm hi\u1ec3u CPython.\\r\\n\\r\\n---\\r\\n\\r\\n## 3. Workflow c\u1ee7a Python \u2013 T\u1eeb l\xfac g\xf5 code \u0111\u1ebfn khi ch\u01b0\u01a1ng tr\xecnh ch\u1ea1y\\r\\n\\r\\nKhi b\u1ea1n ch\u1ea1y m\u1ed9t file Python (`file.py`), Python kh\xf4ng th\u1ef1c thi tr\u1ef1c ti\u1ebfp source code ngay l\u1eadp t\u1ee9c.\\r\\n\\r\\n### Workflow t\u1ed5ng qu\xe1t\\r\\n\\r\\nIDE <br />\\r\\n \u2193 (Save) <br />\\r\\nfile.py (\u1ed4 c\u1ee9ng) <br />\\r\\n \u2193 (Run) <br />\\r\\nSource Code (RAM) <br />\\r\\n \u2193 <br />\\r\\nLexical Analysis \u2192 Tokens (RAM) <br />\\r\\n \u2193 <br />\\r\\nParsing \u2192 AST (RAM) <br />\\r\\n \u2193 <br />\\r\\nCompile <br />\\r\\n \u2193 <br />\\r\\nBytecode (RAM + c\xf3 th\u1ec3 ghi .pyc v\xe0o disk) <br />\\r\\n \u2193 <br />\\r\\nPython Virtual Machine (RAM) <br />\\r\\n \u2193 <br />\\r\\nCPU th\u1ef1c thi <br />\\r\\n\\r\\n\\r\\n### Ph\xe2n t\xedch chi ti\u1ebft\\r\\n\\r\\n**Giai \u0111o\u1ea1n 1: Python \u0111\u1ecdc file.py v\xe0o b\u1ed9 nh\u1edb**\\r\\n(Python Source Code \u2192 RAM)\\r\\n\\r\\nKhi b\u1ea1n ch\u1ea1y: \\r\\n\\r\\n```bash\\r\\npython main.py\\r\\n```\\r\\n\u0110\u1ea7u v\xe0o :\\r\\n- File.py\\r\\n- V\u1ecb tr\xed: \u1ed5 c\u1ee9ng \\r\\n\\r\\nPython l\xe0m g\xec?\\r\\n- H\u1ec7 \u0111i\u1ec1u h\xe0nh \u0111\u1ecdc n\u1ed9i dung file.py\\r\\n- N\u1ea1p to\xe0n b\u1ed9 source code v\xe0o RAM\\r\\n- Chuy\u1ec3n code sang d\u1ea1ng chu\u1ed7i k\xfd t\u1ef1 (text)\\r\\n\\r\\n\u0110\u1ea7u ra :\\r\\n- Source code Python n\u1eb1m trong RAM\\r\\n- File.py v\u1eabn c\xf2n tr\xean \u1ed5 c\u1ee9ng, kh\xf4ng b\u1ecb thay \u0111\u1ed5i\\r\\n\\r\\n\ud83d\udccc T\u1eeb th\u1eddi \u0111i\u1ec3m n\xe0y:\\r\\n\\r\\nPython ch\u1ec9 l\xe0m vi\u1ec7c v\u1edbi code trong RAM\\r\\n\\r\\n\u1ed4 c\u1ee9ng ch\u1ec9 c\xf2n vai tr\xf2 l\u01b0u tr\u1eef\\r\\n\\r\\n---\\r\\n\\r\\n**Giai \u0111o\u1ea1n 2: Lexical Analysis & Parsing**\\r\\n(Source Code \u2192 AST)\\r\\n\\r\\n2.1 Lexical Analysis (Ph\xe2n t\xedch t\u1eeb v\u1ef1ng)\\r\\n\\r\\n\u0110\u1ea7u v\xe0o :\\r\\n- Source code (text) trong RAM\\r\\nV\xed d\u1ee5 :\\r\\n```bash\\r\\na = 10\\r\\n```\\r\\nPython l\xe0m g\xec?\\r\\n\\r\\nChia code th\xe0nh c\xe1c token\\r\\n\\r\\na \u2192 IDENTIFIER\\r\\n\\r\\n= \u2192 OPERATOR\\r\\n\\r\\n10 \u2192 NUMBER\\r\\n\\r\\n\ud83d\udccc L\xfac n\xe0y:\\r\\n\\r\\nPython ch\u01b0a hi\u1ec3u logic\\r\\n\\r\\nCh\u1ec9 m\u1edbi hi\u1ec3u \u201ck\xfd hi\u1ec7u\u201d\\r\\n\\r\\n2.2 Parsing (Ph\xe2n t\xedch c\xfa ph\xe1p)\\r\\n\\r\\n\u0110\u1ea7u v\xe0o :\\r\\n- Token stream (RAM)\\r\\n\\r\\nPython l\xe0m g\xec?\\r\\n- Ki\u1ec3m tra c\xfa ph\xe1p c\xf3 h\u1ee3p l\u1ec7 kh\xf4ng\\r\\n- X\xe2y d\u1ef1ng Abstract Syntax Tree (AST)\\r\\n\\r\\nV\xed d\u1ee5:\\r\\n```bash\\r\\na = 10\\r\\n```\\r\\n\\r\\n\u2192 AST bi\u1ec3u di\u1ec5n:\\r\\n\\r\\n- G\xe1n gi\xe1 tr\u1ecb 10 cho bi\u1ebfn a\\r\\n\\r\\n\u0110\u1ea7u ra :\\r\\n- AST\\r\\n- N\u1eb1m trong RAM\\r\\n\\r\\n\u274c N\u1ebfu sai c\xfa ph\xe1p \u2192 SyntaxError (d\u1eebng t\u1ea1i \u0111\xe2y)\\r\\n\\r\\n---\\r\\n\\r\\n**Giai \u0111o\u1ea1n 3: Compile sang Bytecode**\\r\\n(AST \u2192 Bytecode .pyc)\\r\\n\\r\\n\u0110\u1ea7u v\xe0o :\\r\\n- AST (RAM)\\r\\n\\r\\nPython l\xe0m g\xec?\\r\\n\\r\\n- Bi\xean d\u1ecbch AST th\xe0nh Bytecode\\r\\n\\r\\nBytecode l\xe0:\\r\\n\\r\\n- M\xe3 trung gian\\r\\n\\r\\n- Kh\xf4ng ph\u1ea3i m\xe3 m\xe1y\\r\\n\\r\\n- Kh\xf4ng ph\u1ee5 thu\u1ed9c h\u1ec7 \u0111i\u1ec1u h\xe0nh\\r\\n\\r\\n\u0110\u1ea7u ra :\\r\\n\\r\\n- Bytecode\\r\\n\\r\\n- N\u1eb1m trong RAM\\r\\n\\r\\n\u0110\u1ed3ng th\u1eddi:\\r\\n\\r\\n- Python c\xf3 th\u1ec3 ghi bytecode ra \u1ed5 c\u1ee9ng\\r\\n\\r\\n- D\u01b0\u1edbi d\u1ea1ng file .pyc trong th\u01b0 m\u1ee5c __pycache__\\r\\n\\r\\n\ud83d\udccc Quan tr\u1ecdng:\\r\\n\\r\\n.pyc kh\xf4ng ph\u1ea3i l\xfac n\xe0o c\u0169ng \u0111\u01b0\u1ee3c t\u1ea1o\\r\\n\\r\\nD\xf9ng \u0111\u1ec3:\\r\\n\\r\\n- Ch\u1ea1y nhanh h\u01a1n \u1edf l\u1ea7n sau\\r\\n\\r\\n- Tr\xe1nh compile l\u1ea1i n\u1ebfu code kh\xf4ng \u0111\u1ed5i\\r\\n\\r\\n---\\r\\n\\r\\n**Giai \u0111o\u1ea1n 4: Python Virtual Machine (PVM)**\\r\\n(Bytecode \u2192 Th\u1ef1c thi)\\r\\n\u0110\u1ea7u v\xe0o :\\r\\n- Bytecode (RAM)\\r\\n\\r\\nPython l\xe0m g\xec?\\r\\n\\r\\n+ Python Virtual Machine:\\r\\n\\r\\n-\u0110\u1ecdc t\u1eebng instruction trong bytecode\\r\\n\\r\\n-Th\u1ef1c thi l\u1ea7n l\u01b0\u1ee3t\\r\\n\\r\\n+ M\u1ed7i instruction:\\r\\n\\r\\n- G\u1ecdi h\xe0m C t\u01b0\u01a1ng \u1ee9ng trong CPython\\r\\n\\r\\n- CPU th\u1ef1c hi\u1ec7n l\u1ec7nh th\u1eadt\\r\\n\\r\\n\u0110\u1ea7u ra :\\r\\n\\r\\n- Ch\u01b0\u01a1ng tr\xecnh ch\u1ea1y\\r\\n\\r\\n- T\u1ea1o bi\u1ebfn, object trong heap\\r\\n\\r\\n- In ra m\xe0n h\xecnh, ghi file, g\u1ecdi API, \u2026\\r\\n\\r\\n\ud83d\udccc L\u01b0u \xfd c\u1ef1c quan tr\u1ecdng:\\r\\n\\r\\n- PVM ch\u1ea1y trong RAM\\r\\n\\r\\n- CPU kh\xf4ng ch\u1ea1y source code Python\\r\\n\\r\\n- CPU ch\u1ec9 ch\u1ea1y m\xe3 m\xe1y c\u1ee7a CPython\\r\\n\\r\\n\u27a1\ufe0f V\xec v\u1eady Python th\u01b0\u1eddng \u0111\u01b0\u1ee3c m\xf4 t\u1ea3 l\xe0:\\r\\n\\r\\n> **\u201cInterpreted language with a compilation step\u201d**\\r\\n\\r\\n---\\r\\n\\r\\n## 4. CPython l\xe0 g\xec? V\xec sao n\xf3 quan tr\u1ecdng?\\r\\n\\r\\n### CPython\\r\\n\\r\\nCPython l\xe0 **implementation ph\u1ed5 bi\u1ebfn nh\u1ea5t c\u1ee7a Python**, \u0111\u01b0\u1ee3c vi\u1ebft b\u1eb1ng ng\xf4n ng\u1eef **C**.\\r\\n\\r\\n\ud83d\udc49 Khi b\u1ea1n t\u1ea3i Python t\u1eeb `python.org`, b\u1ea1n \u0111ang s\u1eed d\u1ee5ng **CPython**.\\r\\n\\r\\n### Vai tr\xf2 c\u1ee7a CPython\\r\\n\\r\\n- Bi\xean d\u1ecbch Python code \u2192 Bytecode\\r\\n- Th\u1ef1c thi bytecode th\xf4ng qua PVM\\r\\n- Qu\u1ea3n l\xfd b\u1ed9 nh\u1edb\\r\\n- Cung c\u1ea5p API cho C Extension\\r\\n\\r\\n### C\xe1c implementation kh\xe1c c\u1ee7a Python\\r\\n\\r\\n- **PyPy**: s\u1eed d\u1ee5ng JIT, c\xf3 th\u1ec3 nhanh h\u01a1n CPython\\r\\n- **Jython**: ch\u1ea1y tr\xean JVM\\r\\n- **IronPython**: ch\u1ea1y tr\xean .NET\\r\\n\\r\\n\u27a1\ufe0f Tuy nhi\xean, **CPython v\u1eabn l\xe0 ti\xeau chu\u1ea9n m\u1eb7c \u0111\u1ecbnh**.\\r\\n\\r\\n---\\r\\n\\r\\n## 5. Python qu\u1ea3n l\xfd b\u1ed9 nh\u1edb nh\u01b0 th\u1ebf n\xe0o?\\r\\n\\r\\nPython **t\u1ef1 \u0111\u1ed9ng qu\u1ea3n l\xfd b\u1ed9 nh\u1edb**, l\u1eadp tr\xecnh vi\xean kh\xf4ng c\u1ea7n c\u1ea5p ph\xe1t hay gi\u1ea3i ph\xf3ng th\u1ee7 c\xf4ng.\\r\\n\\r\\n### C\xe1c v\xf9ng b\u1ed9 nh\u1edb ch\xednh\\r\\n\\r\\n1. **Stack Memory**\\r\\n   - L\u01b0u bi\u1ebfn c\u1ee5c b\u1ed9\\r\\n   - Function call\\r\\n\\r\\n2. **Heap Memory**\\r\\n   - L\u01b0u object (list, dict, class instance, \u2026)\\r\\n   - Do CPython qu\u1ea3n l\xfd\\r\\n\\r\\n### Object trong Python g\u1ed3m\\r\\n\\r\\n- Gi\xe1 tr\u1ecb (value)\\r\\n- Ki\u1ec3u d\u1eef li\u1ec7u (type)\\r\\n- Reference count (s\u1ed1 l\u01b0\u1ee3ng tham chi\u1ebfu)\\r\\n\\r\\n---\\r\\n\\r\\n## 6. Garbage Collection trong Python\\r\\n\\r\\n### Reference Counting\\r\\n\\r\\nPython s\u1eed d\u1ee5ng **reference counting** l\xe0m c\u01a1 ch\u1ebf ch\xednh.\\r\\n\\r\\n- M\u1ed7i object c\xf3 s\u1ed1 l\u01b0\u1ee3ng reference\\r\\n- Khi reference = 0 \u2192 object b\u1ecb gi\u1ea3i ph\xf3ng\\r\\n\\r\\nV\xed d\u1ee5:\\r\\n\\r\\n```python\\r\\na = []\\r\\nb = a\\r\\n\\r\\ndel a\\r\\ndel b  # l\xfac n\xe0y object list m\u1edbi b\u1ecb gi\u1ea3i ph\xf3ng\\r\\n```\\r\\n\\r\\n## 7. T\u1ed5ng k\u1ebft\\r\\n\\r\\nTham kh\u1ea3o slide chi ti\u1ebft t\u1ea1i \u0111\xe2y :\\r\\n- \ud83d\udd17 https://www.canva.com/design/DAG_3zWkweQ/ZLs9aa_VVotSC-yXgsAZOw/edit\\r\\n\\r\\nPython l\xe0 ng\xf4n ng\u1eef c\xf3 c\xfa ph\xe1p \u0111\u01a1n gi\u1ea3n, d\u1ec5 h\u1ecdc, nh\u01b0ng **b\xean trong c\xf3 c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng t\u01b0\u01a1ng \u0111\u1ed1i ph\u1ee9c t\u1ea1p**. Khi ch\u1ea1y m\u1ed9t ch\u01b0\u01a1ng tr\xecnh Python, source code kh\xf4ng \u0111\u01b0\u1ee3c th\u1ef1c thi tr\u1ef1c ti\u1ebfp m\xe0 ph\u1ea3i tr\u1ea3i qua nhi\u1ec1u giai \u0111o\u1ea1n nh\u01b0 ph\xe2n t\xedch c\xfa ph\xe1p, bi\xean d\u1ecbch sang bytecode v\xe0 th\u1ef1c thi th\xf4ng qua **Python Virtual Machine (PVM)**.\\r\\n\\r\\nPython kh\xf4ng ph\u1ea3i l\xe0 interpreted thu\u1ea7n t\xfay, m\xe0 l\xe0 **ng\xf4n ng\u1eef th\xf4ng d\u1ecbch c\xf3 b\u01b0\u1edbc bi\xean d\u1ecbch trung gian**. **CPython** gi\u1eef vai tr\xf2 trung t\xe2m trong vi\u1ec7c bi\xean d\u1ecbch, th\u1ef1c thi v\xe0 qu\u1ea3n l\xfd b\u1ed9 nh\u1edb. Nh\u1edd c\u01a1 ch\u1ebf **qu\u1ea3n l\xfd b\u1ed9 nh\u1edb t\u1ef1 \u0111\u1ed9ng v\xe0 Garbage Collection**, Python gi\xfap l\u1eadp tr\xecnh vi\xean t\u1eadp trung v\xe0o logic thay v\xec x\u1eed l\xfd t\xe0i nguy\xean.\\r\\n\\r\\nVi\u1ec7c hi\u1ec3u r\xf5 workflow v\xe0 c\u01a1 ch\u1ebf b\xean trong c\u1ee7a Python gi\xfap l\u1eadp tr\xecnh vi\xean vi\u1ebft code hi\u1ec7u qu\u1ea3 h\u01a1n, debug t\u1ed1t h\u01a1n v\xe0 c\xf3 n\u1ec1n t\u1ea3ng \u0111\u1ec3 h\u1ecdc s\xe2u v\u1ec1 Python trong c\xe1c h\u1ec7 th\u1ed1ng l\u1edbn."},{"id":"bai-viet-dau-tien","metadata":{"permalink":"/my-docusaurus/blog/bai-viet-dau-tien","editUrl":"https://github.com/facebook/docusaurus/tree/main/packages/create-docusaurus/templates/shared/blog/2026-01-22-huong-dan-docusaurus.md","source":"@site/blog/2026-01-22-huong-dan-docusaurus.md","title":"H\u01b0\u1edbng d\u1eabn t\u1ea1o Blog c\xe1 nh\xe2n b\u1eb1ng Docusaurus","description":"Trong b\xe0i vi\u1ebft n\xe0y, m\xecnh s\u1ebd h\u01b0\u1edbng d\u1eabn chi ti\u1ebft c\xe1ch t\u1ea1o m\u1ed9t blog c\xe1 nh\xe2n b\u1eb1ng Docusaurus \u2013 m\u1ed9t c\xf4ng c\u1ee5 r\u1ea5t m\u1ea1nh \u0111\u1ec3 x\xe2y d\u1ef1ng website t\xe0i li\u1ec7u v\xe0 blog t\u0129nh.","date":"2026-01-22T00:00:00.000Z","tags":[{"inline":false,"label":"Docusaurus","permalink":"/my-docusaurus/blog/tags/docusaurus","description":"Docusaurus tag description"},{"inline":true,"label":"blog","permalink":"/my-docusaurus/blog/tags/blog"},{"inline":true,"label":"huong-dan","permalink":"/my-docusaurus/blog/tags/huong-dan"},{"inline":true,"label":"lap-trinh","permalink":"/my-docusaurus/blog/tags/lap-trinh"}],"readingTime":1.07,"hasTruncateMarker":false,"authors":[{"name":"Mai Duc Anh","title":"Blogger & Developer","url":"https://github.com/maiducanha1anh","imageURL":"https://github.com/yourusername.png","key":"admin","page":null}],"frontMatter":{"slug":"bai-viet-dau-tien","title":"H\u01b0\u1edbng d\u1eabn t\u1ea1o Blog c\xe1 nh\xe2n b\u1eb1ng Docusaurus","authors":["admin"],"tags":["docusaurus","blog","huong-dan","lap-trinh"]},"unlisted":false,"prevItem":{"title":"T\xecm hi\u1ec3u v\u1ec1 ng\xf4n ng\u1eef Python \u2013 T\u1eeb t\u1ed5ng quan \u0111\u1ebfn c\u01a1 ch\u1ebf ho\u1ea1t \u0111\u1ed9ng b\xean trong","permalink":"/my-docusaurus/blog/tim-hieu-python"}},"content":"Trong b\xe0i vi\u1ebft n\xe0y, m\xecnh s\u1ebd h\u01b0\u1edbng d\u1eabn chi ti\u1ebft c\xe1ch t\u1ea1o m\u1ed9t blog c\xe1 nh\xe2n b\u1eb1ng **Docusaurus** \u2013 m\u1ed9t c\xf4ng c\u1ee5 r\u1ea5t m\u1ea1nh \u0111\u1ec3 x\xe2y d\u1ef1ng website t\xe0i li\u1ec7u v\xe0 blog t\u0129nh.\\r\\n\\r\\nB\xe0i vi\u1ebft ph\xf9 h\u1ee3p cho:\\r\\n- Sinh vi\xean IT  \\r\\n- Ng\u01b0\u1eddi m\u1edbi h\u1ecdc web  \\r\\n- Ng\u01b0\u1eddi mu\u1ed1n c\xf3 blog c\xe1 nh\xe2n chuy\xean nghi\u1ec7p  \\r\\n\\r\\n---\\r\\n\\r\\n## 1. Docusaurus l\xe0 g\xec?\\r\\n\\r\\nDocusaurus l\xe0 m\u1ed9t framework m\xe3 ngu\u1ed3n m\u1edf do Facebook ph\xe1t tri\u1ec3n, d\xf9ng \u0111\u1ec3 t\u1ea1o:\\r\\n- Blog c\xe1 nh\xe2n  \\r\\n- Website t\xe0i li\u1ec7u  \\r\\n- Website gi\u1edbi thi\u1ec7u d\u1ef1 \xe1n  \\r\\n\\r\\n\u01afu \u0111i\u1ec3m:\\r\\n- Mi\u1ec5n ph\xed  \\r\\n- D\u1ec5 d\xf9ng  \\r\\n- Vi\u1ebft b\xe0i b\u1eb1ng Markdown  \\r\\n- Deploy d\u1ec5 l\xean GitHub Pages  \\r\\n\\r\\n---\\r\\n\\r\\n## 2. Chu\u1ea9n b\u1ecb m\xf4i tr\u01b0\u1eddng\\r\\n\\r\\nB\u1ea1n c\u1ea7n c\xe0i s\u1eb5n:\\r\\n\\r\\n- Node.js (phi\xean b\u1ea3n >= 18)\\r\\n- npm (\u0111i k\xe8m Node.js)\\r\\n\\r\\nKi\u1ec3m tra b\u1eb1ng l\u1ec7nh:\\r\\n\\r\\n```bash\\r\\nnode -v\\r\\nnpm -v\\r\\n```\\r\\n---\\r\\n## 3.C\xe1c b\u01b0\u1edbc t\u1ea1o Blog v\u1edbi Docusaurus\\r\\n\\r\\n\\r\\nSlide d\u01b0\u1edbi \u0111\xe2y m\xf4 t\u1ea3 to\xe0n b\u1ed9 quy tr\xecnh x\xe2y d\u1ef1ng website,\\r\\nt\u1eeb b\u01b0\u1edbc kh\u1edfi t\u1ea1o project cho \u0111\u1ebfn khi deploy (tri\u1ec3n khai) website l\xean GitHub Pages.\\r\\n\\r\\n Xem slide h\u01b0\u1edbng d\u1eabn chi ti\u1ebft t\u1ea1i \u0111\xe2y:\\r\\n- \ud83d\udd17 https://www.canva.com/design/DAG-x-HN2J0/AXmxIe_VDDip6aalEPP8PQ/view\\r\\n\\r\\n(Slide s\u1ebd m\u1edf \u1edf tab m\u1edbi \u0111\u1ec3 xem \u0111\u1ea7y \u0111\u1ee7 v\xe0 r\xf5 r\xe0ng h\u01a1n)\\r\\n\\r\\n---\\r\\n\\r\\n## 4. K\u1ebft lu\u1eadn\\r\\nSau khi xem slide, ng\u01b0\u1eddi m\u1edbi c\xf3 th\u1ec3:\\r\\n\\r\\n- T\u1ea1o project Docusaurus\\r\\n- Vi\u1ebft b\xe0i blog\\r\\n- \u0110\u1ea9y source code l\xean GitHub\\r\\n- Deploy website b\u1eb1ng GitHub Pages\\r\\n\\r\\n---"}]}}')}}]);